files.content:
:root {
  --bg: #1a1c2c;
  --panel: #29366f;
  --ink: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #b13e53;
  --focus: #38b764;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background: var(--bg);
  color: var(--ink);
  font-family: ui-monospace, 'Courier New', monospace;
  font-size: 18px;
  line-height: 1.5;
}

.card {
  width: min(420px, 100%);
  background: var(--panel);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 #000;
  padding: 24px;
  text-align: center;
  image-rendering: pixelated;
}

h1 {
  margin: 0 0 16px;
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

#question {
  margin: 0 0 20px;
  font-size: 22px;
  min-height: 33px;
}

.answers {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 20px;
}

button {
  font: inherit;
  color: var(--ink);
  background: var(--accent-dark);
  border: 3px solid var(--ink);
  padding: 12px 8px;
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
}

button:hover:not(:disabled) { background: #d44f63; }
button:active:not(:disabled) {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #000;
}
button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.score-line {
  margin: 0 0 20px;
  font-size: 18px;
}

#score { color: var(--accent); font-weight: bold; }

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

#next { background: #38b764; }
#next:hover:not(:disabled) { background: #4ad07a; }

@media (max-width: 400px) {
  .card { padding: 16px; }
  .answers, .controls { grid-template-columns: 1fr; }
}

(function () {
  'use strict';

  var state = {
    step: 0,
    score: 0,
    locked: false
  };

  var questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  function render() {
    scoreEl.textContent = String(state.score);

    if (state.step >= questions.length) {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      nextBtn.disabled = true;
      return;
    }

    var q = questions[state.step];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.disabled = state.locked;
    answerB.disabled = state.locked;
    nextBtn.disabled = !state.locked;
  }

  function choose(key) {
    if (state.locked || state.step >= questions.length) return;
    state.locked = true;
    if (questions[state.step].correct === key) {
      state.score += 1;
    }
    render();
  }

  answerA.addEventListener('click', function () { choose('a'); });
  answerB.addEventListener('click', function () { choose('b'); });

  nextBtn.addEventListener('click', function () {
    if (!state.locked || state.step >= questions.length) return;
    state.step += 1;
    state.locked = false;
    render();
  });

  restartBtn.addEventListener('click', function () {
    state.step = 0;
    state.score = 0;
    state.locked = false;
    render();
  });

  render();
})();
